import React from "react";

const Testimonial = () => {
  return (
    <div>
      <h1>what they've said</h1>
      <div>
        <div>
          <div>
            <img />
            <div>
              <p>Name</p>
              <span>Ratting</span>
            </div>
          </div>
          <div>
            <p>FeedBack</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Testimonial;
